def candyWithTies(ratings):
    vals = []
    cnt = []
    for x in ratings:
        if vals and vals[-1] == x:
            cnt[-1] += 1
        else:
            vals.append(x)
            cnt.append(1)
    m = len(vals)
    c = [1] * m
    for i in range(1, m):
        if vals[i] > vals[i - 1]:
            c[i] = c[i - 1] + 1
    for i in range(m - 2, -1, -1):
        if vals[i] > vals[i + 1] and c[i] <= c[i + 1]:
            c[i] = c[i + 1] + 1
    return sum(ci * k for ci, k in zip(c, cnt))
